"""Where things live in the repository. Large inputs are regenerated by `bench data` and ignored by git."""
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DATA = ROOT / "data"
RAW = DATA / "raw"
SPLITS = DATA / "splits.json"
DATA_MANIFEST = DATA / "MANIFEST.json"
RUNS = ROOT / "runs"
VENDOR_CHESS = ROOT / "vendor" / "chess"


def bird_root(config: dict) -> Path:
    """CHESS's DB_ROOT_PATH: the parent of `dev_databases/`."""
    return DATA / "bird_dev" / config["data"]["bird_dev_databases"]["root"]


def sqlite_path(config: dict, db_id: str) -> Path:
    return bird_root(config) / "dev_databases" / db_id / f"{db_id}.sqlite"
